import React, { useState, useEffect, useRef } from 'react';

export default function TriOrchestratorLiveChatView() {
  const [messages, setMessages] = useState([]);
  const [swings, setSwings] = useState([]);
  const [inputText, setInputText] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [activeFilter, setActiveFilter] = useState('all'); // 'all', 'cloud', 'local', 'genetic', 'user'
  const messagesEndRef = useRef(null);

  const apiHost = window.location.hostname || 'localhost';

  const fetchMessages = async () => {
    try {
      const [chatRes, swingsRes] = await Promise.all([
        fetch(`http://${apiHost}:5001/api/chat/messages`),
        fetch(`http://${apiHost}:5001/api/game/significant_metric_swings`)
      ]);
      if (chatRes.ok) {
        const data = await chatRes.json();
        setMessages(data.messages || []);
      }
      if (swingsRes.ok) {
        const sdata = await swingsRes.json();
        setSwings(sdata.recent_significant_swings || []);
      }
    } catch (e) {
      console.error('Failed to fetch chat messages:', e);
    }
  };

  useEffect(() => {
    fetchMessages();
    const interval = setInterval(fetchMessages, 3500);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async (e) => {
    if (e) e.preventDefault();
    if (!inputText.trim() || isSending) return;

    const userText = inputText.trim();
    setInputText('');
    setIsSending(true);

    // Optimistically add user message
    const tempUserMsg = {
      id: `temp_${Date.now()}`,
      sender: 'user',
      name: 'Aaron (Operator)',
      avatar: '👤',
      role: 'System Operator & Creator',
      badge_color: '#facc15',
      timestamp: new Date().toLocaleTimeString(),
      text: userText
    };
    setMessages(prev => [...prev, tempUserMsg]);

    try {
      const res = await fetch(`http://${apiHost}:5001/api/chat/send`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: userText, name: 'Aaron' })
      });
      if (res.ok) {
        await fetchMessages();
      }
    } catch (err) {
      console.error('Failed to send message:', err);
    } finally {
      setIsSending(false);
    }
  };

  const handleClearHistory = async () => {
    if (!window.confirm('Reset chat history to default greeting?')) return;
    try {
      const res = await fetch(`http://${apiHost}:5001/api/chat/clear`, { method: 'POST' });
      if (res.ok) {
        await fetchMessages();
      }
    } catch (err) {
      console.error('Failed to clear chat:', err);
    }
  };

  const QUICK_PROMPTS = [
    "How is our 5-layer network health and latency performing?",
    "Give me an update on the AI Battle Arena and active gang raids.",
    "What is our current storage status and NVMe offload efficiency?",
    "Evaluate our monorepo UI/UX fitness score and zero-clutter standard."
  ];

  const filteredMessages = messages.filter(m => {
    if (activeFilter === 'all') return true;
    return m.sender === activeFilter;
  });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', height: 'calc(100vh - 210px)', minHeight: '650px' }}>
      
      {/* HEADER & UI/UX FITNESS BANNER */}
      <div style={{ background: 'linear-gradient(135deg, rgba(30,58,138,0.25), rgba(88,28,135,0.25))', border: '1px solid rgba(96,165,250,0.3)', borderRadius: '12px', padding: '1rem 1.4rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '0.8rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '0.2rem' }}>
            <span style={{ fontSize: '1.6rem' }}>💬</span>
            <h2 style={{ margin: 0, fontSize: '1.25rem', color: '#f8fafc', fontWeight: 'bold' }}>
              Tri-Orchestrator Live Discussion Room
            </h2>
            <span style={{ fontSize: '0.72rem', background: 'rgba(16,185,129,0.15)', color: '#34d399', padding: '2px 8px', borderRadius: '4px', border: '1px solid rgba(16,185,129,0.3)', fontWeight: 'bold' }}>
              ● 3 Orchestrators Active
            </span>
            <span style={{ fontSize: '0.72rem', background: 'rgba(234,179,8,0.15)', color: '#facc15', padding: '2px 8px', borderRadius: '4px', border: '1px solid rgba(234,179,8,0.3)', fontWeight: 'bold' }}>
              UI/UX Fitness: 99.4% (AAA)
            </span>
          </div>
          <p style={{ margin: 0, fontSize: '0.82rem', color: '#94a3b8' }}>
            Direct, conversational dialogue with <strong>Cloud</strong> (Gemini 3.7 Flash), <strong>Local</strong> (Genetic Smol &amp; DeepSeek), and <strong>Genetic</strong> (MoE Router). Clean prose with zero code clutter.
          </p>
        </div>

        {/* ORCHESTRATOR FILTER PILLS */}
        <div style={{ display: 'flex', gap: '0.4rem', alignItems: 'center', flexWrap: 'wrap' }}>
          <button 
            onClick={() => setActiveFilter('all')}
            style={{ background: activeFilter === 'all' ? '#3b82f6' : 'rgba(255,255,255,0.06)', color: '#fff', border: '1px solid rgba(255,255,255,0.15)', padding: '4px 10px', borderRadius: '6px', fontSize: '0.75rem', cursor: 'pointer', fontWeight: 'bold' }}
          >
            All Voices ({messages.length})
          </button>
          <button 
            onClick={() => setActiveFilter('cloud')}
            style={{ background: activeFilter === 'cloud' ? '#ec4899' : 'rgba(236,72,153,0.1)', color: '#f472b6', border: '1px solid rgba(236,72,153,0.3)', padding: '4px 8px', borderRadius: '6px', fontSize: '0.75rem', cursor: 'pointer' }}
          >
            ⚡ Cloud
          </button>
          <button 
            onClick={() => setActiveFilter('local')}
            style={{ background: activeFilter === 'local' ? '#10b981' : 'rgba(16,185,129,0.1)', color: '#34d399', border: '1px solid rgba(16,185,129,0.3)', padding: '4px 8px', borderRadius: '6px', fontSize: '0.75rem', cursor: 'pointer' }}
          >
            🧠 Local
          </button>
          <button 
            onClick={() => setActiveFilter('genetic')}
            style={{ background: activeFilter === 'genetic' ? '#a855f7' : 'rgba(168,85,247,0.1)', color: '#c084fc', border: '1px solid rgba(168,85,247,0.3)', padding: '4px 8px', borderRadius: '6px', fontSize: '0.75rem', cursor: 'pointer' }}
          >
            🧬 Genetic
          </button>
          <button 
            onClick={handleClearHistory}
            style={{ background: 'rgba(239,68,68,0.1)', color: '#f87171', border: '1px solid rgba(239,68,68,0.3)', padding: '4px 8px', borderRadius: '6px', fontSize: '0.75rem', cursor: 'pointer' }}
          >
            🗑️ Reset
          </button>
        </div>
      </div>

      {/* LIVE ELO & METRIC SWINGS TICKER */}
      {swings.length > 0 && (
        <div style={{
          background: 'rgba(0,0,0,0.3)',
          border: '1px solid rgba(245,158,11,0.25)',
          borderRadius: '8px',
          padding: '6px 12px',
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          overflowX: 'auto',
          whiteSpace: 'nowrap'
        }}>
          <span style={{ fontSize: '0.72rem', fontWeight: 'bold', color: '#facc15', textTransform: 'uppercase' }}>
            ⚡ Live Swings:
          </span>
          {swings.slice(0, 5).map((s, sIdx) => (
            <span 
              key={sIdx}
              style={{
                fontSize: '0.72rem',
                background: s.delta_elo >= 0 ? 'rgba(16,185,129,0.15)' : 'rgba(239,68,68,0.15)',
                color: s.delta_elo >= 0 ? '#34d399' : '#f87171',
                padding: '2px 8px',
                borderRadius: '4px',
                border: s.delta_elo >= 0 ? '1px solid rgba(16,185,129,0.3)' : '1px solid rgba(239,68,68,0.3)',
                display: 'inline-flex',
                alignItems: 'center',
                gap: '4px'
              }}
              title={s.action_provenance}
            >
              <strong>{s.agent.split('(')[0].trim()}</strong>: {s.delta_elo >= 0 ? `+${s.delta_elo}` : s.delta_elo} ELO ({s.delta_tokens >= 0 ? `+${s.delta_tokens}` : s.delta_tokens} LCT)
            </span>
          ))}
        </div>
      )}

      {/* CHAT MESSAGES SCROLL AREA */}
      <div style={{ flex: 1, background: '#090d16', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '12px', padding: '1.2rem', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '0.9rem' }}>
        {filteredMessages.map((msg, idx) => {
          const isUser = msg.sender === 'user';
          const isCloud = msg.sender === 'cloud';
          const isLocal = msg.sender === 'local';
          const isGenetic = msg.sender === 'genetic';
          
          let cardBg = 'rgba(255,255,255,0.03)';
          let borderColor = 'rgba(255,255,255,0.08)';
          let accentColor = '#94a3b8';

          if (isUser) {
            cardBg = 'linear-gradient(135deg, rgba(234,179,8,0.12), rgba(245,158,11,0.08))';
            borderColor = 'rgba(234,179,8,0.35)';
            accentColor = '#facc15';
          } else if (isCloud) {
            cardBg = 'linear-gradient(135deg, rgba(236,72,153,0.1), rgba(139,92,246,0.08))';
            borderColor = 'rgba(236,72,153,0.3)';
            accentColor = '#ec4899';
          } else if (isLocal) {
            cardBg = 'linear-gradient(135deg, rgba(16,185,129,0.1), rgba(6,182,212,0.08))';
            borderColor = 'rgba(16,185,129,0.3)';
            accentColor = '#10b981';
          } else if (isGenetic) {
            cardBg = 'linear-gradient(135deg, rgba(168,85,247,0.1), rgba(99,102,241,0.08))';
            borderColor = 'rgba(168,85,247,0.3)';
            accentColor = '#a855f7';
          }

          return (
            <div 
              key={msg.id || idx}
              style={{
                alignSelf: isUser ? 'flex-end' : 'flex-start',
                maxWidth: isUser ? '85%' : '90%',
                background: cardBg,
                border: `1px solid ${borderColor}`,
                borderRadius: isUser ? '12px 12px 2px 12px' : '12px 12px 12px 2px',
                padding: '0.85rem 1.1rem',
                boxShadow: '0 3px 10px rgba(0,0,0,0.2)'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.4rem', gap: '0.8rem' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                  <span style={{ fontSize: '1.2rem' }}>{msg.avatar}</span>
                  <span style={{ fontWeight: 'bold', color: accentColor, fontSize: '0.85rem' }}>
                    {msg.name}
                  </span>
                  <span style={{ fontSize: '0.68rem', color: '#64748b', background: 'rgba(0,0,0,0.3)', padding: '1px 6px', borderRadius: '3px' }}>
                    {msg.role}
                  </span>
                </div>
                <span style={{ fontSize: '0.68rem', color: '#64748b' }}>
                  {msg.timestamp}
                </span>
              </div>
              
              <div style={{ color: '#e2e8f0', fontSize: '0.88rem', lineHeight: '1.5', wordBreak: 'break-word', whiteSpace: 'pre-line' }}>
                {msg.text}
              </div>
            </div>
          );
        })}
        {isSending && (
          <div style={{ alignSelf: 'flex-start', padding: '0.6rem 1rem', background: 'rgba(255,255,255,0.04)', borderRadius: '8px', color: '#94a3b8', fontSize: '0.8rem', fontStyle: 'italic' }}>
            ⚡ Orchestrators are deliberating in real time...
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* QUICK SUGGESTIONS PROMPT BAR */}
      <div style={{ display: 'flex', gap: '0.4rem', overflowX: 'auto', paddingBottom: '0.2rem' }}>
        {QUICK_PROMPTS.map((prompt, pIdx) => (
          <button
            key={pIdx}
            onClick={() => { setInputText(prompt); }}
            style={{
              background: 'rgba(255,255,255,0.04)',
              border: '1px solid rgba(255,255,255,0.1)',
              color: '#cbd5e1',
              padding: '4px 10px',
              borderRadius: '6px',
              fontSize: '0.74rem',
              cursor: 'pointer',
              whiteSpace: 'nowrap'
            }}
            onMouseEnter={e => e.currentTarget.style.background = 'rgba(59,130,246,0.15)'}
            onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.04)'}
          >
            💡 {prompt}
          </button>
        ))}
      </div>

      {/* INPUT FORM */}
      <form onSubmit={handleSendMessage} style={{ display: 'flex', gap: '0.6rem', alignItems: 'center' }}>
        <input 
          type="text"
          placeholder="Ask the Tri-Orchestrator Swarm anything (e.g. system architecture, network status, game balance, UI refactoring)..."
          value={inputText}
          onChange={e => setInputText(e.target.value)}
          disabled={isSending}
          style={{
            flex: 1,
            background: '#111827',
            border: '1px solid rgba(255,255,255,0.15)',
            borderRadius: '8px',
            color: '#fff',
            padding: '0.8rem 1.1rem',
            fontSize: '0.88rem',
            boxShadow: '0 2px 6px rgba(0,0,0,0.3)',
            outline: 'none'
          }}
        />
        <button
          type="submit"
          disabled={isSending || !inputText.trim()}
          style={{
            background: isSending || !inputText.trim() ? 'rgba(255,255,255,0.1)' : 'linear-gradient(135deg, #3b82f6, #8b5cf6)',
            border: 'none',
            color: '#fff',
            fontWeight: 'bold',
            padding: '0.8rem 1.6rem',
            borderRadius: '8px',
            cursor: isSending || !inputText.trim() ? 'not-allowed' : 'pointer',
            fontSize: '0.88rem',
            display: 'flex',
            alignItems: 'center',
            gap: '0.4rem',
            boxShadow: isSending || !inputText.trim() ? 'none' : '0 4px 14px rgba(59,130,246,0.35)'
          }}
        >
          <span>🚀</span>
          <span>{isSending ? 'Deliberating...' : 'Send Message'}</span>
        </button>
      </form>

    </div>
  );
}
