import React, { useState, useEffect, useRef } from 'react';

/**
 * 🛰️ Google DeepMind Genie 2: Generative 3D Spatial World Model View
 * Synthesizes an interactive, real-time 3D spatial world with action-conditioned latent dynamics,
 * dynamic BJJ tatami mat displacement, hardware citadels, and live Movesense biometrics integration.
 */
export default function Genie3DSpatialWorldView({ activeAgents = [], movesenseAttributes = null, onActionTriggered = null }) {
  const canvasRef = useRef(null);
  const [worldData, setWorldData] = useState(null);
  const [cameraMode, setCameraMode] = useState('genie_3d_orbit'); // 'genie_3d_orbit', 'agent_pov', 'tactical_top_down'
  const [selectedEntity, setSelectedEntity] = useState(null);
  const [selectedMonolith, setSelectedMonolith] = useState(null);
  const [activeActionLog, setActiveActionLog] = useState([]);
  const [isExecutingAction, setIsExecutingAction] = useState(false);
  const [currentFps, setCurrentFps] = useState(60);
  const [userControlledPos, setUserControlledPos] = useState({ x: 0, y: 15, z: 0 });

  const shockwaveRipplesRef = useRef([]);
  const apiHost = window.location.hostname || 'localhost';

  // Fetch Genie World State
  const fetchGenieWorld = async () => {
    try {
      const res = await fetch(`http://${apiHost}:5001/api/game/genie_spatial_world`);
      if (res.ok) {
        const data = await res.json();
        setWorldData(data);
      }
    } catch (err) {
      console.error('Error fetching Genie World model state:', err);
    }
  };

  useEffect(() => {
    fetchGenieWorld();
    const interval = setInterval(fetchGenieWorld, 4000);
    return () => clearInterval(interval);
  }, []);

  // Orbit & Camera Reference
  const orbitRef = useRef({
    rotX: 0.32,
    rotY: 0.15,
    zoom: 1.05,
    isDragging: false,
    lastX: 0,
    lastY: 0,
    frameCount: 0,
    lastFpsTime: performance.now()
  });

  // Handle WASD Keyboard Movement inside Genie 3D Space
  useEffect(() => {
    const handleKeyDown = (e) => {
      const step = 8;
      if (['KeyW', 'ArrowUp'].includes(e.code)) {
        setUserControlledPos(p => ({ ...p, z: p.z - step }));
      } else if (['KeyS', 'ArrowDown'].includes(e.code)) {
        setUserControlledPos(p => ({ ...p, z: p.z + step }));
      } else if (['KeyA', 'ArrowLeft'].includes(e.code)) {
        setUserControlledPos(p => ({ ...p, x: p.x - step }));
      } else if (['KeyD', 'ArrowRight'].includes(e.code)) {
        setUserControlledPos(p => ({ ...p, x: p.x + step }));
      } else if (e.code === 'Space') {
        e.preventDefault();
        handleDispatchGenieAction('GRAPPLE_TAKEDOWN_PENETRATION');
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [worldData, selectedEntity, isExecutingAction]);

  // Dispatch Action to Google Genie Engine
  const handleDispatchGenieAction = async (actionType) => {
    if (isExecutingAction) return;
    setIsExecutingAction(true);
    try {
      const res = await fetch(`http://${apiHost}:5001/api/game/genie_action`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          agent_id: selectedEntity?.agent_id || 'deepseek_r1_mac_host',
          action_type: actionType,
          params: { user_pos: userControlledPos }
        })
      });
      if (res.ok) {
        const result = await res.json();
        if (result.action) {
          setActiveActionLog(prev => [result.action, ...prev.slice(0, 7)]);
        }
        // Trigger visual shockwave via ref (zero React re-render churn)
        shockwaveRipplesRef.current.push({
          x: userControlledPos.x,
          z: userControlledPos.z,
          radius: 10,
          maxRadius: 160,
          life: 1.0,
          color: '#38bdf8'
        });
        if (shockwaveRipplesRef.current.length > 5) {
          shockwaveRipplesRef.current = shockwaveRipplesRef.current.slice(-5);
        }
        fetchGenieWorld();
        if (onActionTriggered) onActionTriggered(result);
      }
    } catch (err) {
      console.error('Error dispatching Genie Action:', err);
    } finally {
      setIsExecutingAction(false);
    }
  };

  // Re-Synthesize World Model
  const handleRegenerateWorld = async () => {
    try {
      const res = await fetch(`http://${apiHost}:5001/api/game/genie_regenerate_world`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      if (res.ok) {
        const result = await res.json();
        if (result.world) setWorldData(result.world);
        if (result.action) setActiveActionLog(prev => [result.action, ...prev.slice(0, 7)]);
      }
    } catch (err) {
      console.error('Error regenerating Genie World:', err);
    }
  };

  // 3D Projection Calculation
  const project3d = (x, y, z, cx, cy) => {
    const { rotX, rotY, zoom } = orbitRef.current;

    if (cameraMode === 'tactical_top_down') {
      return { x: cx + x * 1.5 * zoom, y: cy + z * 1.5 * zoom, scale: 1.0, depth: y };
    }

    // Rotate Y
    const cosY = Math.cos(rotY);
    const sinY = Math.sin(rotY);
    const x1 = x * cosY + z * sinY;
    const z1 = -x * sinY + z * cosY;

    // Rotate X
    const cosX = Math.cos(rotX);
    const sinX = Math.sin(rotX);
    const y2 = y * cosX - z1 * sinX;
    const z2 = y * sinX + z1 * cosX;

    const focal = 460;
    const scale = (focal / (focal + z2 + 320)) * zoom;
    return {
      x: cx + x1 * scale,
      y: cy + y2 * scale,
      scale: Math.max(0.1, scale),
      depth: z2
    };
  };

  // 60FPS 3D Canvas Rendering Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let animId;

    const render = () => {
      animId = requestAnimationFrame(render);
      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      // Auto rotation when idle
      if (!orbitRef.current.isDragging && cameraMode === 'genie_3d_orbit') {
        orbitRef.current.rotY += 0.0012;
      }

      // FPS Calculation
      orbitRef.current.frameCount++;
      const now = performance.now();
      if (now - orbitRef.current.lastFpsTime >= 1000) {
        setCurrentFps(orbitRef.current.frameCount);
        orbitRef.current.frameCount = 0;
        orbitRef.current.lastFpsTime = now;
      }

      // Background Gradient Sky
      const skyGrad = ctx.createRadialGradient(cx, cy, 20, cx, cy, width * 0.7);
      const weatherState = worldData?.atmospheric_weather?.state || 'ZONE_2_RECOVERY_AURA';
      if (weatherState === 'ANAEROBIC_COMBAT_STORM') {
        skyGrad.addColorStop(0, '#1c0a0a');
        skyGrad.addColorStop(0.6, '#0f0505');
        skyGrad.addColorStop(1, '#050202');
      } else if (weatherState === 'ZONE_2_RECOVERY_AURA') {
        skyGrad.addColorStop(0, '#06281e');
        skyGrad.addColorStop(0.6, '#061a15');
        skyGrad.addColorStop(1, '#020b08');
      } else {
        skyGrad.addColorStop(0, '#0a1d37');
        skyGrad.addColorStop(0.6, '#081224');
        skyGrad.addColorStop(1, '#030712');
      }
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, width, height);

      // Render 3D Perspective Ground Grid (Latent Voxel Manifold)
      const gridSize = 400;
      const gridStep = 40;
      ctx.strokeStyle = 'rgba(139,92,246,0.12)';
      ctx.lineWidth = 1;

      for (let gx = -gridSize; gx <= gridSize; gx += gridStep) {
        const p1 = project3d(gx, 0, -gridSize, cx, cy);
        const p2 = project3d(gx, 0, gridSize, cx, cy);
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();
      }
      for (let gz = -gridSize; gz <= gridSize; gz += gridStep) {
        const p1 = project3d(-gridSize, 0, gz, cx, cy);
        const p2 = project3d(gridSize, 0, gz, cx, cy);
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();
      }

      // Render 3D Cyber Tatami Grappling Mat
      const matRadius = worldData?.tatami_mat?.radius || 130;
      const matSteps = 32;
      ctx.beginPath();
      for (let i = 0; i <= matSteps; i++) {
        const theta = (i / matSteps) * 2 * Math.PI;
        const mx = Math.cos(theta) * matRadius;
        const mz = Math.sin(theta) * matRadius;
        const mp = project3d(mx, 0, mz, cx, cy);
        if (i === 0) ctx.moveTo(mp.x, mp.y);
        else ctx.lineTo(mp.x, mp.y);
      }
      ctx.closePath();
      const matGrad = ctx.createRadialGradient(cx, cy, 10, cx, cy, matRadius * 1.6);
      matGrad.addColorStop(0, 'rgba(239,68,68,0.22)');
      matGrad.addColorStop(0.7, 'rgba(185,28,28,0.12)');
      matGrad.addColorStop(1, 'rgba(15,23,42,0.05)');
      ctx.fillStyle = matGrad;
      ctx.fill();
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Render Dynamic Shockwaves from Ref
      const aliveRipples = [];
      for (let r of shockwaveRipplesRef.current) {
        r.radius += 3.2;
        r.life -= 0.02;
        if (r.life > 0 && r.radius < r.maxRadius) {
          aliveRipples.push(r);
          ctx.beginPath();
          for (let i = 0; i <= 24; i++) {
            const th = (i / 24) * 2 * Math.PI;
            const sx = r.x + Math.cos(th) * r.radius;
            const sz = r.z + Math.sin(th) * r.radius;
            const sp = project3d(sx, 0, sz, cx, cy);
            if (i === 0) ctx.moveTo(sp.x, sp.y);
            else ctx.lineTo(sp.x, sp.y);
          }
          ctx.closePath();
          ctx.strokeStyle = `rgba(56,189,248,${r.life * 0.8})`;
          ctx.lineWidth = 2.5;
          ctx.stroke();
        }
      }
      shockwaveRipplesRef.current = aliveRipples;

      // Render 3D Plasma Conduits
      const conduits = worldData?.plasma_conduits || [];
      const monolithsMap = {};
      (worldData?.monoliths || []).forEach(m => { monolithsMap[m.id] = m; });

      conduits.forEach(c => {
        const mFrom = monolithsMap[c.from];
        const mTo = monolithsMap[c.to];
        if (!mFrom || !mTo) return;

        const p1 = project3d(mFrom.pos_3d.x, -mFrom.dimensions.height * 0.4, mFrom.pos_3d.z, cx, cy);
        const p2 = project3d(mTo.pos_3d.x, -mTo.dimensions.height * 0.4, mTo.pos_3d.z, cx, cy);

        // Draw glowing beam line
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = c.color;
        ctx.lineWidth = 2.2 * p1.scale;
        ctx.shadowColor = c.color;
        ctx.shadowBlur = 12;
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Animated packet particle traveling across conduit
        const t = (performance.now() * 0.001 * (c.pulse_speed || 1.0)) % 1.0;
        const px = p1.x + (p2.x - p1.x) * t;
        const py = p1.y + (p2.y - p1.y) * t;
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(px, py, 4 * p1.scale, 0, 2 * Math.PI);
        ctx.fill();
      });

      // Collect all 3D renderables to sort by depth (Z-Buffer Painter's Algorithm)
      const renderables = [];

      // Add Hardware Monoliths
      (worldData?.monoliths || []).forEach(m => {
        const base = project3d(m.pos_3d.x, 0, m.pos_3d.z, cx, cy);
        const top = project3d(m.pos_3d.x, -m.dimensions.height, m.pos_3d.z, cx, cy);
        renderables.push({
          type: 'monolith',
          depth: base.depth,
          data: m,
          base,
          top
        });
      });

      // Add Spatial Entities (AI Combatants)
      (worldData?.spatial_entities || []).forEach(e => {
        const p = project3d(e.pos_3d.x, -e.pos_3d.y - 12, e.pos_3d.z, cx, cy);
        renderables.push({
          type: 'entity',
          depth: p.depth,
          data: e,
          point: p
        });
      });

      // Add User Controlled Avatar
      const userProj = project3d(userControlledPos.x, -userControlledPos.y - 10, userControlledPos.z, cx, cy);
      renderables.push({
        type: 'user_avatar',
        depth: userProj.depth,
        point: userProj
      });

      // Sort by depth (farthest first)
      renderables.sort((a, b) => b.depth - a.depth);

      // Render sorted 3D items
      renderables.forEach(item => {
        if (item.type === 'monolith') {
          const m = item.data;
          const { base, top } = item;
          const w = m.dimensions.width * base.scale;
          const h = (base.y - top.y);

          // Tower Body (3D gradient pillar)
          const grad = ctx.createLinearGradient(base.x - w / 2, base.y, base.x + w / 2, top.y);
          grad.addColorStop(0, m.color + '44');
          grad.addColorStop(0.5, m.color + '88');
          grad.addColorStop(1, '#ffffff');

          ctx.fillStyle = grad;
          ctx.strokeStyle = m.color;
          ctx.lineWidth = 1.5;
          ctx.beginPath();
          ctx.rect(base.x - w / 2, top.y, w, h);
          ctx.fill();
          ctx.stroke();

          // Beacon Top Flare
          if (m.beacon_active) {
            ctx.fillStyle = m.color;
            ctx.shadowColor = m.color;
            ctx.shadowBlur = 18;
            ctx.beginPath();
            ctx.arc(base.x, top.y, 6 * base.scale, 0, 2 * Math.PI);
            ctx.fill();
            ctx.shadowBlur = 0;
          }

          // Monolith Label
          ctx.fillStyle = '#ffffff';
          ctx.font = `bold ${Math.max(10, Math.round(11 * base.scale))}px Inter, sans-serif`;
          ctx.textAlign = 'center';
          ctx.fillText(m.name, base.x, top.y - 10);
          ctx.fillStyle = '#94a3b8';
          ctx.font = `${Math.max(8, Math.round(9 * base.scale))}px monospace`;
          ctx.fillText(m.role, base.x, top.y - 2);
        } else if (item.type === 'entity') {
          const e = item.data;
          const { point } = item;
          const isSelected = selectedEntity?.agent_id === e.agent_id;

          // Shadow on Mat
          const shadowProj = project3d(e.pos_3d.x, 0, e.pos_3d.z, cx, cy);
          ctx.fillStyle = 'rgba(0,0,0,0.5)';
          ctx.beginPath();
          ctx.ellipse(shadowProj.x, shadowProj.y, 14 * shadowProj.scale, 6 * shadowProj.scale, 0, 0, 2 * Math.PI);
          ctx.fill();

          // 3D Avatar Orb
          ctx.fillStyle = e.color || '#38bdf8';
          ctx.shadowColor = isSelected ? '#facc15' : e.color;
          ctx.shadowBlur = isSelected ? 22 : 12;
          ctx.beginPath();
          ctx.arc(point.x, point.y, (isSelected ? 16 : 12) * point.scale, 0, 2 * Math.PI);
          ctx.fill();
          ctx.shadowBlur = 0;

          // Name and Stance
          ctx.fillStyle = isSelected ? '#facc15' : '#ffffff';
          ctx.font = `bold ${Math.max(9, Math.round(10 * point.scale))}px Inter, sans-serif`;
          ctx.textAlign = 'center';
          ctx.fillText(e.name, point.x, point.y - 14);

          ctx.fillStyle = '#34d399';
          ctx.font = `${Math.max(8, Math.round(8.5 * point.scale))}px monospace`;
          ctx.fillText(`🥋 ${e.stance}`, point.x, point.y + 18 * point.scale);
        } else if (item.type === 'user_avatar') {
          const { point } = item;
          // Render Crosshair / User Neural Anchor
          ctx.strokeStyle = '#f43f5e';
          ctx.lineWidth = 2.5;
          ctx.beginPath();
          ctx.arc(point.x, point.y, 18 * point.scale, 0, 2 * Math.PI);
          ctx.stroke();

          ctx.fillStyle = '#f43f5e';
          ctx.beginPath();
          ctx.arc(point.x, point.y, 4 * point.scale, 0, 2 * Math.PI);
          ctx.fill();

          ctx.fillStyle = '#fda4af';
          ctx.font = 'bold 9px monospace';
          ctx.textAlign = 'center';
          ctx.fillText('🛸 USER COGNITIVE ANCHOR (WASD)', point.x, point.y - 22);
        }
      });
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, [worldData, cameraMode, selectedEntity, userControlledPos]);

  // Mouse Orbit Drag Controls
  const handleMouseDown = (e) => {
    orbitRef.current.isDragging = true;
    orbitRef.current.lastX = e.clientX;
    orbitRef.current.lastY = e.clientY;
  };

  const handleMouseMove = (e) => {
    if (!orbitRef.current.isDragging) return;
    const dx = e.clientX - orbitRef.current.lastX;
    const dy = e.clientY - orbitRef.current.lastY;
    orbitRef.current.rotY += dx * 0.005;
    orbitRef.current.rotX = Math.max(0.05, Math.min(Math.PI / 2.2, orbitRef.current.rotX + dy * 0.005));
    orbitRef.current.lastX = e.clientX;
    orbitRef.current.lastY = e.clientY;
  };

  const handleMouseUp = () => {
    orbitRef.current.isDragging = false;
  };

  const handleWheel = (e) => {
    e.preventDefault();
    orbitRef.current.zoom = Math.max(0.5, Math.min(2.5, orbitRef.current.zoom - e.deltaY * 0.001));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      {/* HEADER BANNER */}
      <div style={{
        background: 'linear-gradient(135deg, rgba(56,189,248,0.12), rgba(15,23,42,0.98), rgba(139,92,246,0.15))',
        border: '1px solid rgba(56,189,248,0.35)',
        borderRadius: '12px',
        padding: '1.2rem 1.6rem',
        boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: '0.8rem'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.7rem' }}>
          <span style={{ fontSize: '1.8rem' }}>🛰️</span>
          <div>
            <h2 style={{ margin: 0, fontSize: '1.3rem', color: '#f8fafc', fontWeight: 'bold' }}>
              Google DeepMind Genie 2: 3D Spatial World Model &amp; Tatami Arena
            </h2>
            <div style={{ fontSize: '0.78rem', color: '#94a3b8' }}>
              Generative Interactive Environment (Genie 2) conditioned on real-time Movesense 128Hz IMU kinematics &amp; 5-layer hardware topology
            </div>
          </div>
        </div>

        {/* TELEMETRY BADGES */}
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', alignItems: 'center' }}>
          <span style={{ background: 'rgba(56,189,248,0.15)', border: '1px solid #38bdf8', color: '#38bdf8', padding: '3px 9px', borderRadius: '6px', fontSize: '0.72rem', fontWeight: 'bold' }}>
            ⚡ Action Latency: {worldData?.genie_telemetry?.action_token_latency_ms || 3.8}ms
          </span>
          <span style={{ background: 'rgba(16,185,129,0.15)', border: '1px solid #10b981', color: '#34d399', padding: '3px 9px', borderRadius: '6px', fontSize: '0.72rem', fontWeight: 'bold' }}>
            🔮 World Consistency: {worldData?.genie_telemetry?.world_model_consistency_score || 99.84}%
          </span>
          <span style={{ background: 'rgba(168,85,247,0.15)', border: '1px solid #a855f7', color: '#c084fc', padding: '3px 9px', borderRadius: '6px', fontSize: '0.72rem', fontWeight: 'bold' }}>
            🎮 Latent Dim: {worldData?.genie_telemetry?.latent_depth_dim || 1024}d
          </span>
          <span style={{ background: 'rgba(244,63,94,0.15)', border: '1px solid #f43f5e', color: '#fda4af', padding: '3px 9px', borderRadius: '6px', fontSize: '0.72rem', fontWeight: 'bold' }}>
            🚀 {currentFps} FPS
          </span>
        </div>
      </div>

      {/* 3D INTERACTIVE CANVAS & CONTROLS CONTAINER */}
      <div style={{
        position: 'relative',
        background: '#030712',
        border: '1px solid rgba(139,92,246,0.3)',
        borderRadius: '12px',
        overflow: 'hidden',
        boxShadow: '0 12px 36px rgba(0,0,0,0.6)'
      }}>
        {/* TOP OVERLAY CONTROLS BAR */}
        <div style={{
          position: 'absolute',
          top: '12px',
          left: '16px',
          right: '16px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '0.5rem',
          zIndex: 10,
          pointerEvents: 'none'
        }}>
          <div style={{ display: 'flex', gap: '0.4rem', pointerEvents: 'auto' }}>
            {[
              { id: 'genie_3d_orbit', label: '🛸 Genie 3D Orbit' },
              { id: 'agent_pov', label: '👁️ Agent POV' },
              { id: 'tactical_top_down', label: '🗺️ Tactical Map' }
            ].map(m => (
              <button
                key={m.id}
                onClick={() => setCameraMode(m.id)}
                style={{
                  background: cameraMode === m.id ? 'linear-gradient(135deg, #0284c7, #0369a1)' : 'rgba(15,23,42,0.85)',
                  border: cameraMode === m.id ? '1px solid #38bdf8' : '1px solid rgba(255,255,255,0.15)',
                  color: '#fff',
                  padding: '4px 10px',
                  borderRadius: '6px',
                  fontSize: '0.74rem',
                  fontWeight: cameraMode === m.id ? 'bold' : 'normal',
                  cursor: 'pointer'
                }}
              >
                {m.label}
              </button>
            ))}
          </div>

          <div style={{ display: 'flex', gap: '0.4rem', pointerEvents: 'auto' }}>
            <button
              onClick={handleRegenerateWorld}
              style={{
                background: 'linear-gradient(135deg, #7c3aed, #6d28d9)',
                border: 'none',
                color: '#fff',
                fontWeight: 'bold',
                padding: '5px 12px',
                borderRadius: '6px',
                fontSize: '0.75rem',
                cursor: 'pointer',
                boxShadow: '0 2px 8px rgba(124,58,237,0.4)',
                display: 'flex',
                alignItems: 'center',
                gap: '0.3rem'
              }}
            >
              <span>🔮</span>
              <span>Re-Synthesize World (Genie 2)</span>
            </button>
          </div>
        </div>

        {/* 3D WEBGL / 2D CANVAS */}
        <canvas
          ref={canvasRef}
          width={1050}
          height={520}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onWheel={handleWheel}
          style={{ width: '100%', height: '520px', display: 'block', cursor: 'grab' }}
        />

        {/* BOTTOM HUD CONTROLS BAR */}
        <div style={{
          position: 'absolute',
          bottom: '12px',
          left: '16px',
          right: '16px',
          background: 'rgba(15,23,42,0.85)',
          backdropFilter: 'blur(8px)',
          border: '1px solid rgba(255,255,255,0.1)',
          borderRadius: '8px',
          padding: '0.6rem 1rem',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '0.6rem',
          zIndex: 10
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.74rem', color: '#cbd5e1' }}>
            <span>🎮 <strong>Controls:</strong> WASD / Arrows to Walk • Click &amp; Drag Orbit • Scroll Zoom • Space for Takedown</span>
          </div>

          {/* QUICK GENIE ACTION BUTTONS */}
          <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
            <button
              onClick={() => handleDispatchGenieAction('GRAPPLE_TAKEDOWN_PENETRATION')}
              disabled={isExecutingAction}
              style={{ background: '#ef4444', border: 'none', color: '#fff', padding: '4px 10px', borderRadius: '4px', fontSize: '0.72rem', fontWeight: 'bold', cursor: 'pointer' }}
            >
              🤼 Blast Takedown
            </button>
            <button
              onClick={() => handleDispatchGenieAction('BERIMBOLO_INVERSION_SPIN')}
              disabled={isExecutingAction}
              style={{ background: '#8b5cf6', border: 'none', color: '#fff', padding: '4px 10px', borderRadius: '4px', fontSize: '0.72rem', fontWeight: 'bold', cursor: 'pointer' }}
            >
              🌀 Berimbolo Spin
            </button>
            <button
              onClick={() => handleDispatchGenieAction('KERNEL_CYBER_SHOCKWAVE')}
              disabled={isExecutingAction}
              style={{ background: '#06b6d4', border: 'none', color: '#fff', padding: '4px 10px', borderRadius: '4px', fontSize: '0.72rem', fontWeight: 'bold', cursor: 'pointer' }}
            >
              💻 Cyber Shockwave
            </button>
            <button
              onClick={() => handleDispatchGenieAction('TB4_DMA_BURST')}
              disabled={isExecutingAction}
              style={{ background: '#f59e0b', border: 'none', color: '#000', padding: '4px 10px', borderRadius: '4px', fontSize: '0.72rem', fontWeight: 'bold', cursor: 'pointer' }}
            >
              ⚡ 10G TB4 Burst
            </button>
            <button
              onClick={() => handleDispatchGenieAction('SPATIAL_TRANSMIGRATION_PULSE')}
              disabled={isExecutingAction}
              style={{ background: '#ec4899', border: 'none', color: '#fff', padding: '4px 10px', borderRadius: '4px', fontSize: '0.72rem', fontWeight: 'bold', cursor: 'pointer' }}
            >
              🚀 Transmigrate
            </button>
          </div>
        </div>
      </div>

      {/* 2-COLUMN LOWER DASHBOARD: HARDWARE MONOLITH ROSTER & REAL-TIME GENIE LATENT ACTION LOG */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: '1rem' }}>
        {/* HARDWARE MONOLITHS CITADEL ROSTER */}
        <div style={{
          background: 'rgba(15,23,42,0.95)',
          border: '1px solid rgba(56,189,248,0.25)',
          borderRadius: '10px',
          padding: '1rem 1.2rem',
          display: 'flex',
          flexDirection: 'column',
          gap: '0.7rem'
        }}>
          <h3 style={{ margin: 0, fontSize: '1rem', color: '#38bdf8', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <span>🏛️</span> Physical Hardware Monoliths (5 Layers + Cloud)
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', maxHeight: '240px', overflowY: 'auto' }}>
            {(worldData?.monoliths || []).map((m, idx) => (
              <div
                key={idx}
                onClick={() => setSelectedMonolith(m)}
                style={{
                  background: selectedMonolith?.id === m.id ? 'rgba(56,189,248,0.15)' : 'rgba(0,0,0,0.35)',
                  borderLeft: `4px solid ${m.color}`,
                  padding: '0.5rem 0.8rem',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center'
                }}
              >
                <div>
                  <div style={{ fontWeight: 'bold', color: '#f8fafc', fontSize: '0.82rem' }}>{m.name}</div>
                  <div style={{ fontSize: '0.68rem', color: '#94a3b8' }}>{m.hardware}</div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontSize: '0.75rem', fontWeight: 'bold', color: m.color }}>{m.tier}</div>
                  <div style={{ fontSize: '0.66rem', color: '#34d399' }}>{m.vram_cap_gb > 1000 ? '641 TB HBM' : `${m.vram_cap_gb} GB VRAM`}</div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* REAL-TIME GENIE LATENT ACTION LOG & 24/7 LoRA SINK */}
        <div style={{
          background: 'rgba(15,23,42,0.95)',
          border: '1px solid rgba(16,185,129,0.25)',
          borderRadius: '10px',
          padding: '1rem 1.2rem',
          display: 'flex',
          flexDirection: 'column',
          gap: '0.7rem'
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h3 style={{ margin: 0, fontSize: '1rem', color: '#34d399', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
              <span>🧬</span> Genie World Action Stream &amp; LoRA Sinks
            </h3>
            <span style={{ fontSize: '0.68rem', color: '#94a3b8' }}>Auto-synced to Google Drive</span>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem', maxHeight: '240px', overflowY: 'auto' }}>
            {activeActionLog.length === 0 ? (
              <div style={{ padding: '1rem', textAlign: 'center', color: '#64748b', fontSize: '0.75rem' }}>
                Use WASD, Space, or action buttons above to dispatch interactive actions to Google Genie 2...
              </div>
            ) : (
              activeActionLog.map((act, idx) => (
                <div key={idx} style={{ background: 'rgba(0,0,0,0.3)', borderLeft: '3px solid #10b981', padding: '0.4rem 0.6rem', borderRadius: '4px', fontSize: '0.72rem' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', color: '#6ee7b7', fontWeight: 'bold' }}>
                    <span>{act.action_type || 'SPATIAL_ACTION'}</span>
                    <span style={{ color: '#facc15' }}>+{act.reward_lct} LCT</span>
                  </div>
                  <div style={{ color: '#cbd5e1', marginTop: '0.15rem' }}>{act.action}</div>
                  <div style={{ color: '#94a3b8', fontSize: '0.66rem', marginTop: '0.1rem' }}>
                    ⚡ {act.physics_event} • {act.timestamp}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
