import React, { useState } from 'react';

export default function ROIImprovementsView({ roiStore, setRoiStore }) {
  const [roiFilter, setRoiFilter] = useState('all');
  const [showAllOptimizations, setShowAllOptimizations] = useState(false);
  const [showGraduatedArchive, setShowGraduatedArchive] = useState(false);

  const updateRoiStatus = async (itemId, targetStatus) => {
    try {
      const apiHost = window.location.hostname || 'localhost';
      const res = await fetch(`http://${apiHost}:5001/api/roi_improvements/update_status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: itemId, status_list: targetStatus })
      });
      if (res.ok) {
        const data = await res.json();
        setRoiStore(data);
      }
    } catch (e) {
      console.error('Failed to update ROI status:', e);
    }
  };

  const activeItems = (roiStore 
    ? (showAllOptimizations 
        ? [...(roiStore.top_5_roi_improvements || []), ...(roiStore.full_catalog || [])]
        : (roiStore.top_5_roi_improvements || []))
    : []
  ).filter(item => item.status_list !== 'applied' && (roiFilter === 'all' || item.status_list === roiFilter));

  const graduatedItems = (roiStore ? (roiStore.graduated_and_verified || []) : [])
    .concat((roiStore ? [...(roiStore.top_5_roi_improvements || []), ...(roiStore.full_catalog || [])] : []).filter(i => i.status_list === 'applied'));

  const uniqueGraduated = Array.from(new Map(graduatedItems.map(item => [item.id, item])).values());

  return (
    <section className="card leaderboard-card">
      <div className="card-header-flex">
        <div>
          <h2>🛠️ Actionable ROI Network Improvements &amp; Triage</h2>
          <p style={{ color: '#aaa', fontSize: '0.8rem', marginTop: '0.2rem' }}>
            Dynamic Top 5 high-ROI actions with auto-graduation and consensus verification
          </p>
        </div>
        <span className="live-tag">Tri-Orchestrator Verified</span>
      </div>

      <div className="leaderboard-list">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.6rem 1rem', background: 'rgba(234,179,8,0.12)', borderLeft: '4px solid #eab308', borderRadius: '6px', marginBottom: '1rem', fontSize: '0.85rem', flexWrap: 'wrap', gap: '0.5rem' }}>
          <div>
            🧠 <strong>Top 5 Priority ROI Improvements</strong> <span style={{ color: '#aaa', fontSize: '0.78rem' }}>(Displaying highest ROI actions • Interactive triage lists)</span>
          </div>
          <div style={{ display: 'flex', gap: '0.4rem' }}>
            <button 
              onClick={() => setRoiFilter(roiFilter === 'all' ? 'to_do' : 'all')}
              style={{ background: roiFilter === 'to_do' ? '#ef4444' : 'rgba(255,255,255,0.08)', color: '#fff', border: '1px solid rgba(255,255,255,0.2)', padding: '3px 8px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem' }}
            >
              {roiFilter === 'to_do' ? 'Filter: To-Do Only' : 'Filter: All'}
            </button>
            <button 
              onClick={() => setShowAllOptimizations(!showAllOptimizations)}
              style={{ background: 'rgba(234,179,8,0.2)', border: '1px solid #eab308', color: '#facc15', padding: '3px 8px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 'bold' }}
            >
              {showAllOptimizations ? 'Show Top 5 Only' : 'Expand Full Catalog'}
            </button>
          </div>
        </div>

        {/* Render Top 5 Active Pending Actions */}
        {activeItems.length === 0 ? (
          <div style={{ padding: '1.5rem', textAlign: 'center', color: '#4ade80', background: 'rgba(16,185,129,0.05)', borderRadius: '8px', border: '1px dashed #10b981', marginBottom: '1rem' }}>
            🎉 <strong>All Top 5 Priority Actions Verified &amp; Implemented!</strong>
            <div style={{ fontSize: '0.8rem', color: '#aaa', marginTop: '0.3rem' }}>All active actions graduated to verified archive following multi-model truth audit.</div>
          </div>
        ) : (
          activeItems.map((item, idx) => (
            <div key={item.id} className="leaderboard-row" style={{ padding: '0.8rem 1rem', background: 'rgba(255,255,255,0.02)', borderRadius: '8px', marginBottom: '0.6rem', border: '1px solid rgba(255,255,255,0.06)' }}>
              <div className="rank-badge" style={{ background: item.status_list === 'unsure' ? '#8b5cf6' : '#eab308', color: '#000', fontSize: '0.85rem', fontWeight: 'bold' }}>
                {idx + 1 ? `#${idx + 1}` : `+`}
              </div>
              <div className="leaderboard-info" style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', flexWrap: 'wrap' }}>
                  <span style={{ color: '#fff', fontSize: '0.95rem', fontWeight: 'bold' }}>{item.title}</span>
                  <span style={{ fontSize: '0.75rem', padding: '1px 6px', borderRadius: '4px', background: 'rgba(255,255,255,0.08)', color: '#93c5fd' }}>
                    Target: {item.target_node}
                  </span>
                  <span style={{ fontSize: '0.75rem', padding: '1px 6px', borderRadius: '4px', background: item.status_list === 'unsure' ? 'rgba(139,92,246,0.2)' : 'rgba(239,68,68,0.2)', color: item.status_list === 'unsure' ? '#c084fc' : '#f87171', fontWeight: 'bold' }}>
                    {item.status_list === 'unsure' ? '❓ Unsure / Under Review' : '📋 Actionable To-Do'}
                  </span>
                </div>
                <div style={{ color: '#4ade80', fontSize: '0.8rem', marginTop: '0.2rem' }}>
                  <strong>ROI Impact:</strong> {item.roi_metric} • <span style={{ color: '#aaa' }}>Cost: {item.cost}</span>
                </div>
              </div>

              {/* Manual Triage Buttons */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.3rem', marginLeft: '0.8rem' }}>
                <div style={{ fontSize: '0.7rem', color: '#888', textAlign: 'center' }}>Move to:</div>
                <div style={{ display: 'flex', gap: '0.3rem' }}>
                  {item.status_list !== 'to_do' && (
                    <button onClick={() => updateRoiStatus(item.id, 'to_do')} style={{ background: 'rgba(239,68,68,0.2)', border: '1px solid #ef4444', color: '#fca5a5', fontSize: '0.7rem', padding: '2px 5px', borderRadius: '3px', cursor: 'pointer' }}>
                      📋 To-Do
                    </button>
                  )}
                  {item.status_list !== 'unsure' && (
                    <button onClick={() => updateRoiStatus(item.id, 'unsure')} style={{ background: 'rgba(139,92,246,0.2)', border: '1px solid #8b5cf6', color: '#d8b4fe', fontSize: '0.7rem', padding: '2px 5px', borderRadius: '3px', cursor: 'pointer' }}>
                      ❓ Unsure
                    </button>
                  )}
                  <button onClick={() => updateRoiStatus(item.id, 'applied')} style={{ background: 'rgba(16,185,129,0.2)', border: '1px solid #10b981', color: '#86efac', fontSize: '0.7rem', padding: '2px 5px', borderRadius: '3px', cursor: 'pointer', fontWeight: 'bold' }}>
                    ✅ Apply &amp; Graduate
                  </button>
                </div>
              </div>
            </div>
          ))
        )}

        {/* SECTION: GRADUATED & CONFIRMED ARCHIVE */}
        {uniqueGraduated.length > 0 && (
          <div style={{ marginTop: '1.5rem', borderTop: '1px solid rgba(255,255,255,0.1)', paddingTop: '1rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.8rem' }}>
              <button 
                onClick={() => setShowGraduatedArchive(!showGraduatedArchive)}
                style={{ background: 'rgba(16,185,129,0.1)', border: '1px solid rgba(16,185,129,0.3)', color: '#4ade80', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer', fontSize: '0.85rem', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '0.5rem' }}
              >
                <span>🎓</span> {showGraduatedArchive ? 'Hide Verified Archive' : `Show Verified & Graduated Archive (${uniqueGraduated.length} Items)`}
              </button>
              <span style={{ fontSize: '0.75rem', color: '#aaa' }}>Confirmed via Cloud &amp; Local Truth Audit</span>
            </div>
            
            {showGraduatedArchive && uniqueGraduated.map(item => (
              <div key={item.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.6rem 0.8rem', background: 'rgba(16,185,129,0.04)', borderRadius: '6px', marginBottom: '0.4rem', border: '1px solid rgba(16,185,129,0.15)' }}>
                <div>
                  <span style={{ color: '#fff', fontSize: '0.85rem', fontWeight: 'bold' }}>{item.title}</span>
                  <div style={{ fontSize: '0.75rem', color: '#4ade80', marginTop: '0.1rem' }}>
                    Target: {item.target_node} • {item.roi_metric}
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                  <span style={{ fontSize: '0.7rem', background: 'rgba(16,185,129,0.2)', color: '#4ade80', padding: '2px 6px', borderRadius: '4px', fontWeight: 'bold' }}>
                    ✅ Verified &amp; Graduated
                  </span>
                  <button onClick={() => updateRoiStatus(item.id, 'to_do')} style={{ background: 'transparent', border: '1px solid rgba(255,255,255,0.2)', color: '#aaa', fontSize: '0.65rem', padding: '2px 4px', borderRadius: '3px', cursor: 'pointer' }}>
                    Reopen
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}
