import React, { useState, useEffect } from 'react';

export default function AIBenchmarkLeaderboard() {
  const [benchmarkData, setBenchmarkData] = useState(null);
  const [selectedFilter, setSelectedFilter] = useState('ALL'); // 'ALL', 'ORCHESTRATOR', 'INDIVIDUAL', 'SWARM'
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchLeaderboard = async () => {
      try {
        const apiHost = window.location.hostname || 'localhost';
        const res = await fetch(`http://${apiHost}:5001/api/benchmark/leaderboard`);
        if (res.ok) setBenchmarkData(await res.json());
      } catch (e) {
        console.error('Failed to load benchmark leaderboard:', e);
      } finally {
        setLoading(false);
      }
    };

    fetchLeaderboard();
    const interval = setInterval(fetchLeaderboard, 5000);
    return () => clearInterval(interval);
  }, []);

  if (loading && !benchmarkData) {
    return (
      <div style={{ background: '#111827', borderRadius: '10px', padding: '1.5rem', textAlign: 'center', color: '#94a3b8' }}>
        Loading AI Project Benchmarking Leaderboard...
      </div>
    );
  }

  const summary = benchmarkData?.benchmark_summary || {};
  const leaderboard = benchmarkData?.leaderboard || [];
  const pillars = benchmarkData?.benchmark_pillars || [];
  const workflowRouting = benchmarkData?.dynamic_workflow_routing || {};

  return (
    <div style={{ background: '#0f172a', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '12px', padding: '1.2rem', display: 'flex', flexDirection: 'column', gap: '1.2rem' }}>
      
      {/* LEADERBOARD HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem', borderBottom: '1px solid rgba(255,255,255,0.08)', paddingBottom: '0.8rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
            <span style={{ fontSize: '1.5rem' }}>🏆</span>
            <h3 style={{ margin: 0, fontSize: '1.2rem', color: '#f8fafc', fontWeight: 'bold' }}>
              AI Project Benchmarking Leaderboard &amp; Dynamic Workflow Engine
            </h3>
            <span style={{ fontSize: '0.72rem', background: 'rgba(56,189,248,0.15)', color: '#38bdf8', padding: '2px 8px', borderRadius: '4px', border: '1px solid rgba(56,189,248,0.3)', fontWeight: 'bold' }}>
              Dynamic Multi-Tier Metric Evaluator
            </span>
          </div>
          <p style={{ margin: '0.3rem 0 0 0', fontSize: '0.82rem', color: '#94a3b8' }}>
            Dynamic empirical evaluation of <strong>Orchestrators</strong>, <strong>Individual AIs</strong>, and <strong>AI Swarms</strong> guiding task execution routing.
          </p>
        </div>

        {/* PILLAR FILTER CHIPS */}
        <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
          {[
            { id: 'ALL', label: '🌐 All Metrics' },
            { id: 'ORCHESTRATOR', label: '👑 Orchestrator Level' },
            { id: 'INDIVIDUAL', label: '🤖 Individual AI Level' },
            { id: 'SWARM', label: '🐝 AI Swarm Level' }
          ].map(btn => (
            <button
              key={btn.id}
              onClick={() => setSelectedFilter(btn.id)}
              style={{
                background: selectedFilter === btn.id ? 'linear-gradient(135deg, #38bdf8, #818cf8)' : 'rgba(255,255,255,0.04)',
                border: selectedFilter === btn.id ? 'none' : '1px solid rgba(255,255,255,0.1)',
                color: selectedFilter === btn.id ? '#0f172a' : '#cbd5e1',
                fontWeight: 'bold',
                padding: '5px 12px',
                borderRadius: '6px',
                cursor: 'pointer',
                fontSize: '0.76rem'
              }}
            >
              {btn.label}
            </button>
          ))}
        </div>
      </div>

      {/* SUMMARY BANNER */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '0.8rem' }}>
        <div style={{ background: 'rgba(0,0,0,0.35)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '8px', padding: '0.8rem' }}>
          <div style={{ fontSize: '0.7rem', color: '#94a3b8', textTransform: 'uppercase' }}>Top Ranked Orchestrator</div>
          <div style={{ fontSize: '1rem', fontWeight: 'bold', color: '#38bdf8', marginTop: '0.2rem' }}>
            {summary.top_ranked_orchestrator}
          </div>
        </div>
        <div style={{ background: 'rgba(0,0,0,0.35)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '8px', padding: '0.8rem' }}>
          <div style={{ fontSize: '0.7rem', color: '#94a3b8', textTransform: 'uppercase' }}>Top Ranked Local Core</div>
          <div style={{ fontSize: '1rem', fontWeight: 'bold', color: '#34d399', marginTop: '0.2rem' }}>
            {summary.top_ranked_local_engine}
          </div>
        </div>
        <div style={{ background: 'rgba(0,0,0,0.35)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '8px', padding: '0.8rem' }}>
          <div style={{ fontSize: '0.7rem', color: '#94a3b8', textTransform: 'uppercase' }}>Truth Audit Compliance</div>
          <div style={{ fontSize: '1.2rem', fontWeight: 'bold', color: '#a855f7', marginTop: '0.2rem' }}>
            {summary.average_mesh_truth_compliance}
          </div>
        </div>
        <div style={{ background: 'rgba(0,0,0,0.35)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '8px', padding: '0.8rem' }}>
          <div style={{ fontSize: '0.7rem', color: '#94a3b8', textTransform: 'uppercase' }}>Zero Fake Data Mandate</div>
          <div style={{ fontSize: '0.85rem', fontWeight: 'bold', color: '#10b981', marginTop: '0.3rem' }}>
            ✔ 100% Empirically Validated
          </div>
        </div>
      </div>

      {/* LEADERBOARD TABLE */}
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem', textAlign: 'left' }}>
          <thead>
            <tr style={{ background: 'rgba(255,255,255,0.03)', borderBottom: '1px solid rgba(255,255,255,0.1)', color: '#94a3b8' }}>
              <th style={{ padding: '8px 12px' }}>Rank &amp; Model</th>
              <th style={{ padding: '8px 12px' }}>Type &amp; Tier</th>
              <th style={{ padding: '8px 12px' }}>Overall</th>
              {(selectedFilter === 'ALL' || selectedFilter === 'ORCHESTRATOR') && (
                <th style={{ padding: '8px 12px', color: '#38bdf8' }}>👑 Orchestrator Score</th>
              )}
              {(selectedFilter === 'ALL' || selectedFilter === 'INDIVIDUAL') && (
                <th style={{ padding: '8px 12px', color: '#34d399' }}>🤖 Individual Score</th>
              )}
              {(selectedFilter === 'ALL' || selectedFilter === 'SWARM') && (
                <th style={{ padding: '8px 12px', color: '#a855f7' }}>🐝 Swarm Score</th>
              )}
              <th style={{ padding: '8px 12px' }}>Cost / M Tok</th>
              <th style={{ padding: '8px 12px' }}>Dynamic Workflow Guidance</th>
            </tr>
          </thead>
          <tbody>
            {leaderboard.map((m, idx) => {
              const isTop = m.rank === 1;
              const isLocal = m.type.includes('Local') || m.type.includes('Distributed');

              return (
                <tr 
                  key={m.id}
                  style={{ 
                    borderBottom: '1px solid rgba(255,255,255,0.05)',
                    background: isTop ? 'rgba(56,189,248,0.05)' : isLocal ? 'rgba(52,211,153,0.03)' : 'transparent'
                  }}
                >
                  <td style={{ padding: '10px 12px', fontWeight: 'bold', color: isTop ? '#38bdf8' : '#f8fafc' }}>
                    <span style={{ display: 'inline-block', width: '22px' }}>#{m.rank}</span>
                    {m.name}
                  </td>
                  <td style={{ padding: '10px 12px' }}>
                    <span style={{ 
                      fontSize: '0.7rem', 
                      padding: '2px 6px', 
                      borderRadius: '4px',
                      background: isLocal ? 'rgba(16,185,129,0.15)' : 'rgba(139,92,246,0.15)',
                      color: isLocal ? '#34d399' : '#c084fc',
                      border: isLocal ? '1px solid rgba(16,185,129,0.3)' : '1px solid rgba(139,92,246,0.3)'
                    }}>
                      {m.tier}
                    </span>
                  </td>
                  <td style={{ padding: '10px 12px', fontWeight: 'bold', fontSize: '0.95rem', color: m.overall_score >= 97 ? '#38bdf8' : m.overall_score >= 95 ? '#34d399' : '#facc15' }}>
                    {m.overall_score}%
                  </td>
                  {(selectedFilter === 'ALL' || selectedFilter === 'ORCHESTRATOR') && (
                    <td style={{ padding: '10px 12px' }}>
                      <div style={{ fontWeight: 'bold', color: '#38bdf8' }}>{m.orchestrator_metrics?.score}%</div>
                      <div style={{ fontSize: '0.7rem', color: '#64748b' }}>Truth Audit: {m.orchestrator_metrics?.truth_audit_compliance}</div>
                    </td>
                  )}
                  {(selectedFilter === 'ALL' || selectedFilter === 'INDIVIDUAL') && (
                    <td style={{ padding: '10px 12px' }}>
                      <div style={{ fontWeight: 'bold', color: '#34d399' }}>{m.individual_metrics?.score}%</div>
                      <div style={{ fontSize: '0.7rem', color: '#64748b' }}>Syntax Pass: {m.individual_metrics?.code_syntax_pass_rate}</div>
                    </td>
                  )}
                  {(selectedFilter === 'ALL' || selectedFilter === 'SWARM') && (
                    <td style={{ padding: '10px 12px' }}>
                      <div style={{ fontWeight: 'bold', color: '#a855f7' }}>{m.swarm_metrics?.score}%</div>
                      <div style={{ fontSize: '0.7rem', color: '#64748b' }}>RPC Sync: {m.swarm_metrics?.rpc_coordination}</div>
                    </td>
                  )}
                  <td style={{ padding: '10px 12px', fontSize: '0.76rem', color: m.cost_per_m_tokens.includes('$0.00') ? '#34d399' : '#94a3b8', fontWeight: m.cost_per_m_tokens.includes('$0.00') ? 'bold' : 'normal' }}>
                    {m.cost_per_m_tokens}
                  </td>
                  <td style={{ padding: '10px 12px', fontSize: '0.76rem', color: '#cbd5e1', maxWidth: '280px' }}>
                    {m.workflow_guidance}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* DYNAMIC WORKFLOW ROUTING ENGINE */}
      <div style={{ background: 'rgba(0,0,0,0.4)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '8px', padding: '1rem' }}>
        <div style={{ fontSize: '0.85rem', fontWeight: 'bold', color: '#f8fafc', marginBottom: '0.6rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <span>🧭</span> Dynamic AI Workflow Routing (Guided by Benchmark Strengths)
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '0.8rem' }}>
          {Object.entries(workflowRouting).map(([key, route]) => (
            <div key={key} style={{ background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '6px', padding: '0.8rem' }}>
              <div style={{ fontSize: '0.72rem', color: '#38bdf8', fontWeight: 'bold', textTransform: 'uppercase' }}>
                {key.replace(/_/g, ' ')}
              </div>
              <div style={{ fontSize: '0.82rem', fontWeight: 'bold', color: '#f8fafc', marginTop: '0.3rem' }}>
                {route.recommended_primary}
              </div>
              <div style={{ fontSize: '0.7rem', color: '#94a3b8', marginTop: '0.2rem' }}>
                Fallback: {route.recommended_secondary}
              </div>
              <div style={{ fontSize: '0.68rem', color: '#64748b', marginTop: '0.3rem', fontStyle: 'italic' }}>
                {route.rationale}
              </div>
            </div>
          ))}
        </div>
      </div>

    </div>
  );
}
